package com.ledbadge.rubik.cube

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.random.Random

class CubeModelTest {

    /**
     * move_cases.txt is generated by the vendored C++ engine: for a set of
     * sizes it stores 40 deterministic moves (outer, wide and inner slice
     * turns) and the resulting sticker arrays. If the Kotlin model ever drifts
     * from the native one, solutions returned by the solver would no longer
     * replay here, so this test guards the whole pipeline.
     */
    @Test
    fun kotlinModelMatchesNativeEngine() {
        val stream = javaClass.classLoader!!.getResourceAsStream("move_cases.txt")
        checkNotNull(stream) { "move_cases.txt missing" }

        var cases = 0
        stream.bufferedReader().use { reader ->
            while (true) {
                val header = reader.readLine() ?: break
                if (header.isBlank()) continue
                val parts = header.trim().split(Regex("\\s+"))
                val n = parts[0].toInt()
                val count = parts[1].toInt()

                val moves = ArrayList<CubeMove>(count)
                repeat(count) {
                    val line = reader.readLine()!!.trim().split(Regex("\\s+"))
                    moves += CubeMove(
                        face = Face.entries[line[0].toInt()],
                        outerDepth = line[1].toInt(),
                        innerDepth = line[2].toInt(),
                        turn = Turn.entries[line[3].toInt()],
                    )
                }

                val expected = reader.readLine()!!.trim().split(Regex("\\s+")).map { it.toInt() }

                val cube = CubeState(n)
                for (move in moves) cube.apply(move)
                assertEquals("n=$n stickers", expected, cube.toIntArray().toList())

                for (move in moves.asReversed()) cube.apply(move.inverse)
                assertTrue("n=$n inverse scramble", cube.isSolved())

                cases++
            }
        }

        assertTrue("no cases parsed", cases >= 8)
    }

    @Test
    fun quarterTurnsAndHalfTurnsCancel() {
        for (n in 2..6) {
            for (face in Face.entries) {
                val base = CubeState(n)
                val cw = base.applied(CubeMove(face, turn = Turn.CW))
                assertFalse(cw.isSolved())

                val four = cw.copy()
                repeat(3) { four.apply(CubeMove(face, turn = Turn.CW)) }
                assertTrue("CW x4 n=$n $face", four.isSolved())

                val half = base.applied(CubeMove(face, turn = Turn.HALF))
                val twice = half.applied(CubeMove(face, turn = Turn.HALF))
                assertTrue("HALF x2 n=$n $face", twice.isSolved())

                val back = cw.applied(CubeMove(face, turn = Turn.CCW))
                assertTrue("CW then CCW n=$n $face", back.isSolved())
            }
        }
    }

    @Test
    fun wideAndInnerMovesAreReversible() {
        for (n in 3..7) {
            for (face in Face.entries) {
                val wide = CubeMove(face, 0, n / 2 - 1, Turn.CW)
                val inner = CubeMove(face, n / 2, n / 2, Turn.HALF)

                val a = CubeState(n).applied(wide).applied(wide.inverse)
                assertTrue("wide n=$n $face", a.isSolved())

                val b = CubeState(n).applied(inner).applied(inner.inverse)
                assertTrue("inner n=$n $face", b.isSolved())
            }
        }
    }

    @Test
    fun scrambleIsValidAndLeavesCubeUnsolved() {
        for (n in 2..9) {
            val random = Random(n * 31 + 7)
            val moves = Scrambler.generate(n, Scrambler.lengthFor(n), random)
            val cube = CubeState(n)
            for (move in moves) {
                assertTrue("middle slice used n=$n", move.innerDepth < (n / 2).coerceAtLeast(1))
                cube.apply(move)
            }
            assertFalse("scramble should mix n=$n", cube.isSolved())

            for (move in moves.asReversed()) cube.apply(move.inverse)
            assertTrue("scramble inverse n=$n", cube.isSolved())
        }
    }

    @Test
    fun notationFormatting() {
        assertEquals("R", CubeMove(Face.R).notation(3))
        assertEquals("R'", CubeMove(Face.R, turn = Turn.CCW).notation(3))
        assertEquals("U2", CubeMove(Face.U, turn = Turn.HALF).notation(3))
        assertEquals("Rw", CubeMove(Face.R, 0, 1).notation(4))
        assertEquals("3Rw", CubeMove(Face.R, 0, 2).notation(4))
        assertEquals("3F", CubeMove(Face.F, 2, 2).notation(4))
    }
}
